end

function OSManageReportDetailsDialog:GetStableIncomeData()
    local data = {}
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local curLevel = maidCoffeePlayerComponent:GetCafeLevel()
    data.desc = localize("餐厅等级 _num_",{_num_ = string.format("LV%s",curLevel) })
    data.tips = localize("Tips：提升餐厅等级可提高固定收益")
    local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
    local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
    data.goodsId = goodsId

    local vo = MaidCoffeeUtils.GetMaidCoffeeLevelExpVo(curLevel)
    local time = vo.time/60
    local addNum = vo.rewardNum
    local maxNum = vo.rewardNumMax
    local str = localize("每_num1_分钟可固定获得_num2_个新海币，一次最多可积攒_num3_个",{_num1_ = math.floor(time),_num2_ = addNum,_num3_ = maxNum})
    data.skillDes = str
    data.callBack = function()
        local isCattyUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3010)
        if isCattyUnLock then
            UIModule.OpenDialog({id = Constants.UITypeIds.UIMaidCoffeeCattyMain}, {{ id = Constants.UITypeIds.MaidCoffeeReportDetails} })
        else
            GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id3010))
        end
    end
    return data
end

function OSManageReportDetailsDialog:GetStorefrontIncomeData()
    local data = {}
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local aestheticsNum = maidCoffeePlayerComponent:GetAestheticsNum()
    data.desc = localize("美观度 _num_",{_num_ = aestheticsNum})
    data.tips = localize("Tips：提升餐厅美观度可提高技能效果")

    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local curIndex = maidCoffeePlayerComponent:GetCurEffectIndex()
    local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
    local vo = MaidCoffeeUtils.GetAestheticsVo(curIndex)
    ---@type MaidCoffeeSkillVo
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(vo.additionId)
    data.skillDes = ""
    if skillVo then
        data.skillDes = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr, vo.additionNum,nil,vo.percentage)
        data.goodsId = skillVo.rewardId
    end
    data.callBack = function()
        local isRenovaUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3012)
        if isRenovaUnLock then
            local MaidCoffeeDriver = import("Game.MaidCoffee.MaidCoffeeDriver")
            local opDriver = MaidCoffeeDriver.New()
            opDriver:Start({id = Constants.UITypeIds.OverseaRenovaMainDialog})
        else
            GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id3012))
        end
    end
    return data
end

function OSManageReportDetailsDialog:TopTabOnClickHandler(index)
    CfUtils.SetActive(self.RoleManageList.gameObject,index == type.PersonManage)
    CfUtils.SetActive(self.RecommendList.gameObject,index == type.Recommend)
    if index == type.PersonManage then
        self.RoleRootEnv:RefreshShow()
    elseif index == type.Recommend then
        self.RecommendRootEnv:RefreshShow()
        if not self.calculation then
            cs_coroutine.start(function()
                coroutine.yield(Yielders.EndOfFrame)
                self.RecommendRootEnv:RefreshHighLine()
                self.calculation = true
            end)
        end
    elseif index == type.Cat then

    end
end

